//! REF-009 / DEP-009 / NUM-014: the IAU 2006 precession and ecliptic routines (ERFA port) and the
//! typed rotations built on them, against pyerfa 2.0.1.5 goldens at 113 TT epochs spanning
//! 1550-2650, in f64 and double-double.
//!
//! Oracles: `tests/goldens/erfa-frames-pyerfa.csv` (generated by `tools/goldens/erfa_frames.py`,
//! pinned by SHA-256) and the tolerances of vectors `PYERFA-*` in `tests/vectors/frames.toml`.
#![allow(
    clippy::unwrap_used,
    clippy::panic,
    reason = "test helpers: a failed unwrap is a test failure with a clear message"
)]

mod common;

use common::{Golden, load, vectors};
use ferroastro_core::time::{Epoch, Tt};
use ferroastro_erfa::{Matrix3, anpm, eceq06, eqec06, obl06, p06e, pmat06};
use ferroastro_frames::{ecliptic_precession, icrf_to_ecliptic_j2000, icrf_to_ecliptic_of_date};
use ferroastro_real::{DoubleDouble, Real};
use ferroastro_vectors::VectorSet;

const TABLE: &str = "erfa-frames-pyerfa.csv";
const P06E: [&str; 16] = [
    "eps0", "psia", "oma", "bpa", "bqa", "pia", "bpia", "epsa", "chia", "za", "zetaa", "thetaa",
    "pa", "gam", "phi", "psi",
];

#[derive(Default)]
struct Max {
    value: f64,
    at: String,
}

impl Max {
    fn add(&mut self, x: f64, at: impl Fn() -> String) {
        assert!(x.is_finite());
        if x > self.value {
            self.value = x;
            self.at = at();
        }
    }
}

fn check(v: &VectorSet, id: &str, backend: &str, m: &Max) {
    let vector = v.get(id).unwrap();
    println!(
        "{id:<28} {backend:<14} max |diff| {:.3e} {} (at {})",
        m.value, vector.unit, m.at
    );
    if let Err(e) = vector.check(m.value) {
        panic!("{backend}: {e}");
    }
}

fn matrix_diff<R: Real>(g: &Golden, row: &[String], prefix: &str, m: &Matrix3<R>, out: &mut Max) {
    for (i, r) in m.iter().enumerate() {
        for (j, x) in r.iter().enumerate() {
            let col = format!("{prefix}_{}{}", i + 1, j + 1);
            let d = (x.to_f64() - g.f(row, &col)).abs();
            out.add(d, || format!("{col}, k = {}", g.i(row, "k")));
        }
    }
}

fn run<R: Real>(v: &VectorSet) {
    let g = load(TABLE, v, "PYERFA-ECM06-MAX-DIFF");
    assert!(g.rows.len() >= 50, "REF-009/WP9: at least 50 epochs");
    let (mut obl, mut pe, mut pm, mut ec, mut sph, mut ej) = Default::default();
    let ecl_j2000 = icrf_to_ecliptic_j2000::<R>();
    for row in &g.rows {
        let k = g.i(row, "k");
        let (t1, t2) = (R::from_f64(g.f(row, "tt1")), R::from_f64(g.f(row, "tt2")));
        let at = |what: &str| format!("{what}, k = {k}");
        let d = (obl06(t1, t2).to_f64() - g.f(row, "obl06")).abs();
        Max::add(&mut obl, d, || at("obl06"));
        let a = p06e(t1, t2);
        let ours = [
            a.eps0, a.psia, a.oma, a.bpa, a.bqa, a.pia, a.bpia, a.epsa, a.chia, a.za, a.zetaa,
            a.thetaa, a.pa, a.gam, a.phi, a.psi,
        ];
        for (name, x) in P06E.iter().zip(ours) {
            Max::add(&mut pe, (x.to_f64() - g.f(row, name)).abs(), || at(name));
        }
        // p_A through the typed API as well.
        let tt = Epoch::<Tt, R>::from_jd_parts(t1, t2).unwrap();
        let pa = ecliptic_precession(tt).unwrap().p_a.radians().to_f64();
        Max::add(&mut pe, (pa - g.f(row, "pa")).abs(), || at("p_A (frames)"));
        matrix_diff(&g, row, "pmat06", &pmat06(t1, t2), &mut pm);
        matrix_diff(
            &g,
            row,
            "ecm06",
            icrf_to_ecliptic_of_date(tt).matrix(),
            &mut ec,
        );
        let f = |c: &str| R::from_f64(g.f(row, c));
        let (lon, lat) = eqec06(t1, t2, f("eq_ra"), f("eq_dec"));
        let (ra, dec) = eceq06(t1, t2, f("ec_lon"), f("ec_lat"));
        for (ours, col, wrap) in [
            (lon, "eqec06_lon", true),
            (lat, "eqec06_lat", false),
            (ra, "eceq06_ra", true),
            (dec, "eceq06_dec", false),
        ] {
            let mut d = ours - f(col);
            if wrap {
                d = anpm(d);
            }
            Max::add(&mut sph, d.abs().to_f64(), || at(col));
        }
        matrix_diff(&g, row, "eclj2000", ecl_j2000.matrix(), &mut ej);
    }
    let b = R::NAME;
    check(v, "PYERFA-OBL06-MAX-DIFF", b, &obl);
    check(v, "PYERFA-P06E-MAX-DIFF", b, &pe);
    check(v, "PYERFA-PMAT06-MAX-DIFF", b, &pm);
    check(v, "PYERFA-ECM06-MAX-DIFF", b, &ec);
    check(v, "PYERFA-EQEC-ECEQ-MAX-DIFF", b, &sph);
    check(v, "PYERFA-ECLIPJ2000-MAX-DIFF", b, &ej);
}

/// Verifies: REF-009, DEP-009, NUM-014
#[test]
fn pyerfa_precession_and_ecliptic_goldens_f64() {
    run::<f64>(&vectors());
}

/// Verifies: REF-009, DEP-009, NUM-014, DEP-007
#[test]
fn pyerfa_precession_and_ecliptic_goldens_double_double() {
    run::<DoubleDouble>(&vectors());
}
